155		if err != nil {
156			t.Fatalf("parser.ParseFile(%s): %v", path, err)
157		}
158	
159		for _, decl := range file.Decls {
160			gen, ok := decl.(*ast.GenDecl)
161			if !ok || gen.Tok != token.TYPE {
162				continue
163			}
164			for _, spec := range gen.Specs {
165				typeSpec, ok := spec.(*ast.TypeSpec)
166				if !ok || typeSpec.Name.Name != "DeclaredCaps" {
167					continue
168				}
169				doc := typeSpec.Doc
170				if doc == nil {
171					doc = gen.Doc
172				}
173				if doc == nil {
174					t.Fatal("DeclaredCaps must have a doc comment")
175				}
176	
177				var capabilities []string
178				for _, comment := range doc.List {
179					line := strings.TrimSpace(strings.TrimPrefix(comment.Text, "//"))
180					name, ok := strings.CutPrefix(line, "- ")
181					if !ok {
182						continue
183					}
184					if fields := strings.Fields(name); len(fields) != 1 || !ast.IsExported(name) {
185						t.Fatalf("invalid capability entry in DeclaredCaps doc: %q", line)
186					}
187					capabilities = append(capabilities, name)
188				}
189				if len(capabilities) == 0 {
190					t.Fatal("DeclaredCaps doc must list built-in capabilities as '- CapabilityName' entries")
191				}
192				return capabilities
193			}
194		}
