404	// TestAgentPackages_SelfRegister verifies that each agent package has an init()
405	// function that calls agent.Register(). This ensures agents are properly
406	// discoverable via the registry.
407	func TestAgentPackages_SelfRegister(t *testing.T) {
408		t.Parallel()
409	
410		agentDir := findAgentDir(t)
411		agentPkgs := discoverAgentPackages(t, agentDir)
412	
413		if len(agentPkgs) == 0 {
414			t.Fatal("no agent packages found — test setup is broken")
415		}
416	
417		for _, pkgDir := range agentPkgs {
418			pkgName := filepath.Base(pkgDir)
419			t.Run(pkgName, func(t *testing.T) {
420				t.Parallel()
421				if !hasInitWithRegister(t, pkgDir) {
422					t.Errorf("agent package %q has no init() function calling Register() — agents must self-register", pkgName)
423				}
424			})
425		}
426	}
