324	// findAgentDir returns the absolute path to cmd/entire/cli/agent/.
325	// Go test runner sets cwd to the package directory, so os.Getwd() gives us
326	// the agent dir directly.
327	func findAgentDir(t *testing.T) string {
328		t.Helper()
329		wd, err := os.Getwd()
330		if err != nil {
331			t.Fatalf("os.Getwd: %v", err)
332		}
333		return wd
