371	// extractImports parses all Go files in a directory and returns unique import paths.
372	// Includes both production and test files — test-only imports should also respect boundaries.
373	func extractImports(t *testing.T, dir string) []string {
374		t.Helper()
375	
376		fset := token.NewFileSet()
377		// ParseDir is deprecated in favor of go/packages, but we intentionally
378		// scan all files regardless of build tags to catch forbidden imports in test files too.
379		pkgs, err := parser.ParseDir(fset, dir, nil, parser.ImportsOnly) //nolint:staticcheck // Intentionally scan files regardless of build tags.
380		if err != nil {
381			t.Fatalf("parser.ParseDir(%s): %v", dir, err)
382		}
383	
384		seen := make(map[string]bool)
385		for _, pkg := range pkgs {
386			for _, file := range pkg.Files {
387				for _, imp := range file.Imports {
388					path, err := strconv.Unquote(imp.Path.Value)
389					if err != nil {
390						t.Fatalf("strconv.Unquote(%s): %v", imp.Path.Value, err)
391					}
392					seen[path] = true
393				}
394			}
395		}
396	
397		imports := make([]string, 0, len(seen))
398		for imp := range seen {
399			imports = append(imports, imp)
400		}
401		return imports
402	}
