404	// TestAgentPackages_SelfRegister verifies that each agent package has an init()
405	// function that calls agent.Register(). This ensures agents are properly
406	// discoverable via the registry.
407	func TestAgentPackages_SelfRegister(t *testing.T) {
408		t.Parallel()
409	
410		agentDir := findAgentDir(t)
411		agentPkgs := discoverAgentPackages(t, agentDir)
412	
413		if len(agentPkgs) == 0 {
414			t.Fatal("no agent packages found — test setup is broken")
415		}
416	
417		for _, pkgDir := range agentPkgs {
418			pkgName := filepath.Base(pkgDir)
419			t.Run(pkgName, func(t *testing.T) {
420				t.Parallel()
421				if !hasInitWithRegister(t, pkgDir) {
422					t.Errorf("agent package %q has no init() function calling Register() — agents must self-register", pkgName)
423				}
424			})
425		}
426	}
427	
428	// hasInitWithRegister checks if any Go file in the directory has an init()
429	// function that contains a call to Register.
430	func hasInitWithRegister(t *testing.T, dir string) bool {
431		t.Helper()
432	
433		fset := token.NewFileSet()
434		// See extractImports for why this scan uses ParseDir.
435		pkgs, err := parser.ParseDir(fset, dir, func(fi os.FileInfo) bool { //nolint:staticcheck // Intentionally scan files regardless of build tags.
436			return !strings.HasSuffix(fi.Name(), "_test.go")
437		}, 0)
438		if err != nil {
439			t.Fatalf("parser.ParseDir(%s): %v", dir, err)
440		}
441	
442		for _, pkg := range pkgs {
443			for _, file := range pkg.Files {
444				for _, decl := range file.Decls {
445					fn, ok := decl.(*ast.FuncDecl)
446					if !ok || fn.Name.Name != "init" || fn.Recv != nil {
447						continue
448					}
449					// Walk the init body looking for a call to Register or agent.Register
450					found := false
451					ast.Inspect(fn.Body, func(n ast.Node) bool {
452						call, ok := n.(*ast.CallExpr)
453						if !ok {
454							return true
455						}
456						switch fun := call.Fun.(type) {
457						case *ast.Ident:
458							if fun.Name == "Register" {
459								found = true
460							}
461						case *ast.SelectorExpr:
462							if fun.Sel.Name == "Register" {
463								found = true
464							}
465						}
466						return !found
467					})
468					if found {
469						return true
470					}
471				}
472			}
473		}
474		return false
475	}

