  9	func TestRenderAdditionalContextHookOutput(t *testing.T) {
 10		t.Parallel()
 11	
 12		out, err := RenderAdditionalContextHookOutput("UserPromptSubmit", "use entire trail")
 13		if err != nil {
 14			t.Fatalf("RenderAdditionalContextHookOutput: %v", err)
 15		}
 16		if !strings.HasSuffix(string(out), "\n") {
 17			t.Errorf("payload must be newline-terminated, got %q", string(out))
 18		}
 19	
 20		var parsed struct {
 21			HookSpecificOutput struct {
 22				HookEventName     string `json:"hookEventName"`
 23				AdditionalContext string `json:"additionalContext"`
 24			} `json:"hookSpecificOutput"`
 25		}
 26		if err := json.Unmarshal(out, &parsed); err != nil {
 27			t.Fatalf("output is not valid JSON: %v (%q)", err, string(out))
 28		}
 29		if parsed.HookSpecificOutput.HookEventName != "UserPromptSubmit" {
 30			t.Errorf("hookEventName = %q, want UserPromptSubmit", parsed.HookSpecificOutput.HookEventName)
 31		}
 32		if parsed.HookSpecificOutput.AdditionalContext != "use entire trail" {
 33			t.Errorf("additionalContext = %q", parsed.HookSpecificOutput.AdditionalContext)
 34		}
 35	}
