 37	// perms builds a rawPermissions map from a JSON object literal.
 38	func perms(t *testing.T, body string) map[string]json.RawMessage {
 39		t.Helper()
 40		var m map[string]json.RawMessage
 41		require.NoError(t, json.Unmarshal([]byte(body), &m))
 42		return m
 43	}
