 45	// denyOf reads back permissions.deny, or nil when the key is gone.
 46	func denyOf(t *testing.T, m map[string]json.RawMessage) []string {
 47		t.Helper()
 48		raw, ok := m["deny"]
 49		if !ok {
 50			return nil
 51		}
 52		var rules []string
 53		require.NoError(t, json.Unmarshal(raw, &rules))
 54		return rules
 55	}
