// AsCallerSessionIdentifier returns the agent as CallerSessionIdentifier if it
// implements it. Built-in-only capability, so no DeclaredCaps gate.
func AsCallerSessionIdentifier(ag Agent) (CallerSessionIdentifier, bool) {
	return builtinCapability[CallerSessionIdentifier](ag)
}

---

// AsHomeLayoutProvider returns the agent as a HomeLayoutProvider if it is a
// built-in agent that implements the interface.
func AsHomeLayoutProvider(ag Agent) (HomeLayoutProvider, bool) {
	return builtinCapability[HomeLayoutProvider](ag)
}
---

// AsTaskTranscriptMatcher returns the agent as a TaskTranscriptMatcher if it is
// a built-in agent that implements the interface.
func AsTaskTranscriptMatcher(ag Agent) (TaskTranscriptMatcher, bool) {
	return builtinCapability[TaskTranscriptMatcher](ag)
}

